 private function oee(array $o): void {[$code,$date,$oper,$cycle,$total,$good]=$o;$machine=Machine::where('code',$code)->first();$planned=480;$a=$oper/$planned;$p=min(1,($cycle*$total)/$oper);$q=$total? $good/$total:0;OeeRecord::updateOrCreate(['machine_id'=>$machine->id,'recorded_on'=>$date],['planned_minutes'=>$planned,'operating_minutes'=>$oper,'ideal_cycle_minutes'=>$cycle,'total_output'=>$total,'good_output'=>$good,'availability'=>$a,'performance'=>$p,'quality'=>$q,'oee'=>$a*$p*$q]); }
